@Test
public void testSkips() throws Exception {
    TestInStream.OutputCollector collect = new TestInStream.OutputCollector();
    BitFieldWriter out = new BitFieldWriter(new OutStream("test", new StreamOptions(100), collect), 1);
    final int COUNT = 16384;
    for (int i = 0; i < COUNT; ++i) {
        if (i < COUNT / 2) {
            out.write(i & 1);
        } else {
            out.write((i / 3) & 1);
        }
    }
    out.flush();
    ByteBuffer inBuf = ByteBuffer.allocate(collect.buffer.size());
    collect.buffer.setByteBuffer(inBuf, 0, collect.buffer.size());
    inBuf.flip();
    BitFieldReader in = new BitFieldReader(InStream.create("test", new BufferChunk(inBuf, 0), inBuf.remaining()));
    for (int i = 0; i < COUNT; i += 5) {
        int x = in.next();
        if (i < COUNT / 2) {
            assertEquals(i & 1, x);
        } else {
            assertEquals((i / 3) & 1, x);
        }
        if (i < COUNT - 5) {
            in.skip(4);
        }
        in.skip(0);
    }
}

@Test
public void testSeekSkip() throws Exception {
    TestInStream.OutputCollector collect = new TestInStream.OutputCollector();
    BitFieldWriter out = new BitFieldWriter(new OutStream("test", new StreamOptions(100), collect), 1);
    final int COUNT = 256;
    TestInStream.PositionCollector posn = new TestInStream.PositionCollector();
    for (int i = 0; i < COUNT; ++i) {
        if (i == 200) {
            out.getPosition(posn);
        }
        if (i < COUNT / 2) {
            out.write(i & 1);
        } else {
            out.write((i / 3) & 1);
        }
    }
    out.flush();
    ByteBuffer inBuf = ByteBuffer.allocate(collect.buffer.size());
    collect.buffer.setByteBuffer(inBuf, 0, collect.buffer.size());
    inBuf.flip();
    BitFieldReader in = new BitFieldReader(InStream.create("test", new BufferChunk(inBuf, 0), inBuf.remaining()));
    in.seek(posn);
    in.skip(10);
    for (int r = 210; r < COUNT; ++r) {
        int x = in.next();
        if (r < COUNT / 2) {
            assertEquals(r & 1, x);
        } else {
            assertEquals((r / 3) & 1, x);
        }
    }
}

