}

@Test
public void testUncompressed() throws Exception {
    OutputCollector collect = new OutputCollector();
    OutStream out = new OutStream("test", new StreamOptions(100), collect);
    PositionCollector[] positions = new PositionCollector[1024];
    for (int i = 0; i < 1024; ++i) {
        positions[i] = new PositionCollector();
        out.getPosition(positions[i]);
        out.write(i);
    }
    out.flush();
    assertEquals(1024, collect.buffer.size());
    for (int i = 0; i < 1024; ++i) {
        assertEquals((byte) i, collect.buffer.get(i));
    }
    ByteBuffer inBuf = ByteBuffer.allocate(collect.buffer.size());
    collect.buffer.setByteBuffer(inBuf, 0, collect.buffer.size());
    inBuf.flip();
    InStream in = InStream.create("test", new BufferChunk(inBuf, 0), inBuf.remaining());
    assertEquals("uncompressed stream test position: 0 length: 1024" + " range: 0 offset: 0 limit: 1024", in.toString());
    for (int i = 0; i < 1024; ++i) {
        int x = in.read();
        assertEquals(i & 0xff, x);
    }
    for (int i = 1023; i >= 0; --i) {
        in.seek(positions[i]);
        assertEquals(i & 0xff, in.read());
    }
}

@Test
public void testEncrypted() throws Exception {
    final long DATA_CONST = 0x1_0000_0003L;
    final int ROW_COUNT = 1024;
    OutputCollector collect = new OutputCollector();
    EncryptionAlgorithm algorithm = EncryptionAlgorithm.AES_128;
    byte[] rawKey = new byte[algorithm.keyLength()];
    for (int i = 0; i < rawKey.length; ++i) {
        rawKey[i] = (byte) i;
    }
    Key decryptKey = new SecretKeySpec(rawKey, algorithm.getAlgorithm());
    StreamName name = new StreamName(0, OrcProto.Stream.Kind.DATA);
    byte[] iv = CryptoUtils.createIvForStream(algorithm, name, 0);
    StreamOptions writerOptions = new StreamOptions(100).withEncryption(algorithm, decryptKey, iv);
    OutStream out = new OutStream("test", writerOptions, collect);
    PositionCollector[] positions = new PositionCollector[ROW_COUNT];
    DataOutputStream outStream = new DataOutputStream(out);
    for (int i = 0; i < ROW_COUNT; ++i) {
        positions[i] = new PositionCollector();
        out.getPosition(positions[i]);
        outStream.writeLong(i * DATA_CONST);
    }
    out.flush();
    assertEquals(ROW_COUNT * 8, collect.buffer.size());
    // Allocate the stream into three ranges. making sure that they don't fall
    // on the 16 byte aes boundaries.
    int[] rangeSizes = { 1965, ROW_COUNT * 8 - 1965 - 15, 15 };
    int offset = 0;
    BufferChunkList list = new BufferChunkList();
    for (int size : rangeSizes) {
        ByteBuffer buffer = ByteBuffer.allocate(size);
        collect.buffer.setByteBuffer(buffer, offset, size);
        buffer.flip();
        list.add(new BufferChunk(buffer, offset));
        offset += size;
    }
    InStream in = InStream.create("test", list.get(), collect.buffer.size(), InStream.options().withEncryption(algorithm, decryptKey, iv));
    assertEquals("encrypted uncompressed stream test position: 0 length: 8192" + " range: 0 offset: 0 limit: 1965", in.toString());
    DataInputStream inputStream = new DataInputStream(in);
    for (int i = 0; i < ROW_COUNT; ++i) {
        assertEquals("row " + i, i * DATA_CONST, inputStream.readLong());
    }
    for (int i = ROW_COUNT - 1; i >= 0; --i) {
        in.seek(positions[i]);
        assertEquals("row " + i, i * DATA_CONST, inputStream.readLong());
    }
}

@Test
public void testCompressedEncrypted() throws Exception {
    final long DATA_CONST = 0x1_0000_0003L;
    final int ROW_COUNT = 1024;
    OutputCollector collect = new OutputCollector();
    EncryptionAlgorithm algorithm = EncryptionAlgorithm.AES_128;
    byte[] rawKey = new byte[algorithm.keyLength()];
    for (int i = 0; i < rawKey.length; ++i) {
        rawKey[i] = (byte) i;
    }
    Key decryptKey = new SecretKeySpec(rawKey, algorithm.getAlgorithm());
    StreamName name = new StreamName(0, OrcProto.Stream.Kind.DATA);
    byte[] iv = CryptoUtils.createIvForStream(algorithm, name, 0);
    CompressionCodec codec = new ZlibCodec();
    StreamOptions writerOptions = new StreamOptions(500).withCodec(codec, codec.createOptions()).withEncryption(algorithm, decryptKey, iv);
    OutStream out = new OutStream("test", writerOptions, collect);
    PositionCollector[] positions = new PositionCollector[ROW_COUNT];
    DataOutputStream outStream = new DataOutputStream(out);
    for (int i = 0; i < ROW_COUNT; ++i) {
        positions[i] = new PositionCollector();
        out.getPosition(positions[i]);
        outStream.writeLong(i * DATA_CONST);
    }
    out.flush();
    // currently 3957 bytes
    int compressedSize = collect.buffer.size();
    // Allocate the stream into three ranges. making sure that they don't fall
    // on the 16 byte aes boundaries.
    int[] rangeSizes = { 1998, compressedSize - 1998 - 15, 15 };
    int offset = 0;
    BufferChunkList list = new BufferChunkList();
    for (int size : rangeSizes) {
        ByteBuffer buffer = ByteBuffer.allocate(size);
        collect.buffer.setByteBuffer(buffer, offset, size);
        buffer.flip();
        list.add(new BufferChunk(buffer, offset));
        offset += size;
    }
    InStream in = InStream.create("test", list.get(), collect.buffer.size(), InStream.options().withCodec(new ZlibCodec()).withBufferSize(500).withEncryption(algorithm, decryptKey, iv));
    assertEquals("encrypted compressed stream test position: 0 length: " + compressedSize + " range: 0 offset: 0 limit: 1998 range 0 = 0 to" + " 1998;  range 1 = 1998 to " + (compressedSize - 15) + ";  range 2 = " + (compressedSize - 15) + " to " + compressedSize, in.toString());
    DataInputStream inputStream = new DataInputStream(in);
    for (int i = 0; i < ROW_COUNT; ++i) {
        assertEquals("row " + i, i * DATA_CONST, inputStream.readLong());
    }
    for (int i = ROW_COUNT - 1; i >= 0; --i) {
        in.seek(positions[i]);
        assertEquals("row " + i, i * DATA_CONST, inputStream.readLong());
    }
}

