            out.write(i);
        } else {
            out.write(256 * i);
        }
    }
    out.flush();
    ByteBuffer inBuf = ByteBuffer.allocate(collect.buffer.size());
    collect.buffer.setByteBuffer(inBuf, 0, collect.buffer.size());
    inBuf.flip();
    RunLengthIntegerReaderV2 in = new RunLengthIntegerReaderV2(InStream.create("test", new BufferChunk(inBuf, 0), inBuf.remaining()), true, false);
