public void testPredEvalWithDateStats() throws Exception {
    PredicateLeaf pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.LONG, "x", 15L, null);
    // Date to Integer conversion is not possible.
    try {
        evaluateInteger(createDateStats(10, 100), pred);
        fail("evaluate should throw");
    } catch (RecordReaderImpl.SargCastException ia) {
        assertEquals("ORC SARGS could not convert from Date to LONG", ia.getMessage());
    }
    // Date to Float conversion is also not possible.
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.FLOAT, "x", 15.0, null);
    try {
        evaluateInteger(createDateStats(10, 100), pred);
        fail("evaluate should throw");
    } catch (RecordReaderImpl.SargCastException ia) {
        assertEquals("ORC SARGS could not convert from Date to FLOAT", ia.getMessage());
    }
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.STRING, "x", "15", null);
    assertEquals(TruthValue.NO, evaluateInteger(createDateStats(10, 100), pred));
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.STRING, "x", "1970-01-11", null);
    assertEquals(TruthValue.YES_NO, evaluateInteger(createDateStats(10, 100), pred));
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.STRING, "x", "15.1", null);
    assertEquals(TruthValue.NO, evaluateInteger(createDateStats(10, 100), pred));
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.STRING, "x", "__a15__1", null);
    assertEquals(TruthValue.NO, evaluateInteger(createDateStats(10, 100), pred));
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.STRING, "x", "2000-01-16", null);
    assertEquals(TruthValue.NO, evaluateInteger(createDateStats(10, 100), pred));
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.STRING, "x", "1970-01-16", null);
    assertEquals(TruthValue.YES_NO, evaluateInteger(createDateStats(10, 100), pred));
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.DATE, "x", new DateWritable(15).get(), null);
    assertEquals(TruthValue.YES_NO, evaluateInteger(createDateStats(10, 100), pred));
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.DATE, "x", new DateWritable(150).get(), null);
    assertEquals(TruthValue.NO, evaluateInteger(createDateStats(10, 100), pred));
    // Date to Decimal conversion is also not possible.
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.DECIMAL, "x", new HiveDecimalWritable("15"), null);
    try {
        evaluateInteger(createDateStats(10, 100), pred);
        fail("evaluate should throw");
    } catch (RecordReaderImpl.SargCastException ia) {
        assertEquals("ORC SARGS could not convert from Date to DECIMAL", ia.getMessage());
    }
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.TIMESTAMP, "x", new Timestamp(15), null);
    assertEquals(TruthValue.NO, evaluateInteger(createDateStats(10, 100), pred));
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.TIMESTAMP, "x", new Timestamp(15L * 24L * 60L * 60L * 1000L), null);
    assertEquals(TruthValue.YES_NO, evaluateInteger(createDateStats(10, 100), pred));
}

