@Test
public void testUncompressedSeek() throws Exception {
    TestInStream.OutputCollector collect = new TestInStream.OutputCollector();
    RunLengthByteWriter out = new RunLengthByteWriter(new OutStream("test", new StreamOptions(100), collect));
    TestInStream.PositionCollector[] positions = new TestInStream.PositionCollector[2048];
    for (int i = 0; i < 2048; ++i) {
        positions[i] = new TestInStream.PositionCollector();
        out.getPosition(positions[i]);
        if (i < 1024) {
            out.write((byte) (i / 4));
        } else {
            out.write((byte) i);
        }
    }
    out.flush();
    ByteBuffer inBuf = ByteBuffer.allocate(collect.buffer.size());
    collect.buffer.setByteBuffer(inBuf, 0, collect.buffer.size());
    inBuf.flip();
    RunLengthByteReader in = new RunLengthByteReader(InStream.create("test", new BufferChunk(inBuf, 0), inBuf.remaining()));
    for (int i = 0; i < 2048; ++i) {
        int x = in.next() & 0xff;
        if (i < 1024) {
            assertEquals((i / 4) & 0xff, x);
        } else {
            assertEquals(i & 0xff, x);
        }
    }
    for (int i = 2047; i >= 0; --i) {
        in.seek(positions[i]);
        int x = in.next() & 0xff;
        if (i < 1024) {
            assertEquals((i / 4) & 0xff, x);
        } else {
            assertEquals(i & 0xff, x);
        }
    }
}

