    RunLengthIntegerWriter out = new RunLengthIntegerWriter(new OutStream("test", new StreamOptions(100), collect), true);
    for (int i = 0; i < 2048; ++i) {
        if (i < 1024) {
            out.write(i);
        } else {
            out.write(256 * i);
        }
    }
    out.flush();
    ByteBuffer inBuf = ByteBuffer.allocate(collect.buffer.size());
