    batch.size = 1;
    setBigRow(batch, 0, true, (byte) 127, (short) 1024, 42, 42L * 1024 * 1024 * 1024, (float) 3.1415, -2.713, null, null, null, null, null);
    writer.addRowBatch(batch);
