@Test
public void testUnions() throws Exception {
    TypeDescription schema = TypeDescription.createStruct().addField("outer", TypeDescription.createUnion().addUnionChild(TypeDescription.createInt()).addUnionChild(TypeDescription.createLong()));
    Writer writer = OrcFile.createWriter(testFilePath, OrcFile.writerOptions(conf).setSchema(schema).version(fileFormat));
    VectorizedRowBatch batch = schema.createRowBatch();
    batch.size = 1024;
    UnionColumnVector outer = (UnionColumnVector) batch.cols[0];
    batch.cols[0].noNulls = false;
    for (int r = 0; r < 1024; ++r) {
        if (r < 200) {
            outer.isNull[r] = true;
        } else if (r < 300) {
            outer.tags[r] = 0;
        } else if (r < 400) {
            outer.tags[r] = 1;
        } else if (r < 600) {
            outer.isNull[r] = true;
        } else if (r < 800) {
            outer.tags[r] = 1;
        } else if (r < 1000) {
            outer.isNull[r] = true;
        } else {
            outer.tags[r] = 1;
        }
        ((LongColumnVector) outer.fields[0]).vector[r] = r;
        ((LongColumnVector) outer.fields[1]).vector[r] = -r;
    }
    writer.addRowBatch(batch);
    writer.close();
    Reader reader = OrcFile.createReader(testFilePath, OrcFile.readerOptions(conf));
    RecordReader rows = reader.rows();
    batch = reader.getSchema().createRowBatch(1024);
    UnionColumnVector union = (UnionColumnVector) batch.cols[0];
    LongColumnVector ints = (LongColumnVector) union.fields[0];
    LongColumnVector longs = (LongColumnVector) union.fields[1];
    Assert.assertEquals(true, rows.nextBatch(batch));
    assertEquals(1024, batch.size);
    for (int r = 0; r < 1024; ++r) {
        if (r < 200) {
            assertEquals("row " + r, true, union.isNull[r]);
        } else if (r < 300) {
            assertEquals("row " + r, false, union.isNull[r]);
            assertEquals("row " + r, 0, union.tags[r]);
            assertEquals("row " + r, r, ints.vector[r]);
        } else if (r < 400) {
            assertEquals("row " + r, false, union.isNull[r]);
            assertEquals("row " + r, 1, union.tags[r]);
            assertEquals("row " + r, -r, longs.vector[r]);
        } else if (r < 600) {
            assertEquals("row " + r, true, union.isNull[r]);
        } else if (r < 800) {
            assertEquals("row " + r, false, union.isNull[r]);
            assertEquals("row " + r, 1, union.tags[r]);
            assertEquals("row " + r, -r, longs.vector[r]);
        } else if (r < 1000) {
            assertEquals("row " + r, true, union.isNull[r]);
        } else {
            assertEquals("row " + r, false, union.isNull[r]);
            assertEquals("row " + r, 1, union.tags[r]);
            assertEquals("row " + r, -r, longs.vector[r]);
        }
    }
    Assert.assertEquals(false, rows.nextBatch(batch));
}

/**
 * Test lists and how they interact with the child column. In particular,
 * put nulls between back to back lists and then make some lists that
 * oper lap.
 * @throws Exception
 */
@Test
public void testLists() throws Exception {
    TypeDescription schema = TypeDescription.createStruct().addField("list", TypeDescription.createList(TypeDescription.createLong()));
    Writer writer = OrcFile.createWriter(testFilePath, OrcFile.writerOptions(conf).setSchema(schema).version(fileFormat));
    VectorizedRowBatch batch = schema.createRowBatch();
    batch.size = 1024;
    ListColumnVector list = (ListColumnVector) batch.cols[0];
    list.noNulls = false;
    for (int r = 0; r < 1024; ++r) {
        if (r < 200) {
            list.isNull[r] = true;
        } else if (r < 300) {
            list.offsets[r] = r - 200;
            list.lengths[r] = 1;
        } else if (r < 400) {
            list.isNull[r] = true;
        } else if (r < 500) {
            list.offsets[r] = r - 300;
            list.lengths[r] = 1;
        } else if (r < 600) {
            list.isNull[r] = true;
        } else if (r < 700) {
            list.offsets[r] = r;
            list.lengths[r] = 2;
        } else {
            list.isNull[r] = true;
        }
        ((LongColumnVector) list.child).vector[r] = r * 10;
    }
    writer.addRowBatch(batch);
    writer.close();
    Reader reader = OrcFile.createReader(testFilePath, OrcFile.readerOptions(conf));
    RecordReader rows = reader.rows();
    batch = reader.getSchema().createRowBatch(1024);
    list = (ListColumnVector) batch.cols[0];
    rows.nextBatch(batch);
    assertEquals(1024, batch.size);
    for (int r = 0; r < 1024; ++r) {
        StringBuilder actual = new StringBuilder();
        list.stringifyValue(actual, r);
        if (r < 200) {
            assertEquals("row " + r, "null", actual.toString());
        } else if (r < 300) {
            assertEquals("row " + r, "[" + ((r - 200) * 10) + "]", actual.toString());
        } else if (r < 400) {
            assertEquals("row " + r, "null", actual.toString());
        } else if (r < 500) {
            assertEquals("row " + r, "[" + ((r - 300) * 10) + "]", actual.toString());
        } else if (r < 600) {
            assertEquals("row " + r, "null", actual.toString());
        } else if (r < 700) {
            assertEquals("row " + r, "[" + (10 * r) + ", " + (10 * (r + 1)) + "]", actual.toString());
        } else {
            assertEquals("row " + r, "null", actual.toString());
        }
    }
    Assert.assertEquals(false, rows.nextBatch(batch));
}

