@Test
public void testHadoopKeyProvider() throws IOException {
    HadoopShims shims = new HadoopShimsPre2_7();
    Configuration conf = new Configuration();
    conf.set("hadoop.security.key.provider.path", "test:///");
    // Hard code the random so that we know the bytes that will come out.
    HadoopShims.KeyProvider provider = shims.getKeyProvider(conf, new Random(24));
    List<String> keyNames = provider.getKeyNames();
    assertEquals(2, keyNames.size());
    assertEquals(true, keyNames.contains("pii"));
    assertEquals(true, keyNames.contains("secret"));
    HadoopShims.KeyMetadata piiKey = provider.getCurrentKeyVersion("pii");
    assertEquals(1, piiKey.getVersion());
    HadoopShims.LocalKey localKey = provider.createLocalKey(piiKey);
    Key key = provider.decryptLocalKey(piiKey, localKey.encryptedKey);
    assertEquals(new BytesWritable(localKey.decryptedKey.getEncoded()).toString(), new BytesWritable(key.getEncoded()).toString());
}

@Test
public void testFixedDeltaZero() throws Exception {
    TypeDescription schema = TypeDescription.createInt();
    Writer w = OrcFile.createWriter(testFilePath, OrcFile.writerOptions(conf).compress(CompressionKind.NONE).setSchema(schema).rowIndexStride(0).encodingStrategy(OrcFile.EncodingStrategy.COMPRESSION).version(OrcFile.Version.V_0_12));
    VectorizedRowBatch batch = schema.createRowBatch(5120);
    for (int i = 0; i < 5120; ++i) {
        appendInt(batch, 123);
    }
    w.addRowBatch(batch);
    w.close();
    PrintStream origOut = System.out;
    ByteArrayOutputStream myOut = new ByteArrayOutputStream();
    System.setOut(new PrintStream(myOut));
    FileDump.main(new String[] { testFilePath.toUri().toString() });
    System.out.flush();
    String outDump = new String(myOut.toByteArray());
    // 10 runs of 512 elements. Each run has 2 bytes header, 2 bytes base (base = 123,
    // zigzag encoded varint) and 1 byte delta (delta = 0). In total, 5 bytes per run.
    assertEquals(true, outDump.contains("Stream: column 0 section DATA start: 3 length 50"));
    System.setOut(origOut);
}

