@Test
public void testCustomTimestampFormat() throws Exception {
    String tsFormat = "d[d] MMM yyyy HH:mm:ss";
    StringReader input = new StringReader("'21 Mar 2018 12:23:34'\n" + "'3 Feb 2018 18:04:51'\n");
    TypeDescription schema = TypeDescription.fromString("struct<a:timestamp>");
    RecordReader reader = new CsvReader(input, null, 1, schema, ',', '\'', '\\', 0, "", tsFormat);
    VectorizedRowBatch batch = schema.createRowBatch(2);
